        /// 
        /// To filter default namespace, set to empty string.
        /// </param>
        /// <param name="filterNoNamespace">
        /// Selects only keys without provided namespaces.
        /// 
        /// To filter default namespace, set to empty string.
        /// </param>
        /// <param name="filterTag">Selects only keys with provided tag</param>
        /// <param name="filterNoTag">Selects only keys without provided tag</param>
        /// <param name="filterOutdatedLanguage">Selects only keys, where translation in provided langs is in outdated state</param>
        /// <param name="filterNotOutdatedLanguage">Selects only keys, where translation in provided langs is not in outdated state</param>
        /// <param name="filterRevisionId">Selects only key affected by activity with specidfied revision ID</param>
